import{c as e,Q as o,j as r,m as n}from"./chunks/framework.BXc4yaFE.js";const p=JSON.parse('{"title":"Context Window 與 Context Management 多面向深度研究報告","description":"","frontmatter":{},"headers":[],"relativePath":"research/reports/2026-06-03-context-window-management-deep-research.md","filePath":"research/reports/2026-06-03-context-window-management-deep-research.md","lastUpdated":1780842316000}'),a={name:"research/reports/2026-06-03-context-window-management-deep-research.md"};function d(i,t,s,c,l,h){return o(),r("div",null,[...t[0]||(t[0]=[n('<h1 id="context-window-與-context-management-多面向深度研究報告" tabindex="-1">Context Window 與 Context Management 多面向深度研究報告 <a class="header-anchor" href="#context-window-與-context-management-多面向深度研究報告" aria-label="Permalink to &quot;Context Window 與 Context Management 多面向深度研究報告&quot;">​</a></h1><blockquote><p><strong>研究日期</strong>：2026-06-03 <strong>研究主導模型</strong>：Claude Opus 4.8（1M context, effort=high） <strong>研究方法</strong>：4 個 researcher sub-agent 平行採集（web + arXiv）→ 機械對抗驗證 → 手動合成 <strong>新增論文全文</strong>：11 篇（research/papers/，全 PDF 驗證） <strong>信度分層</strong>：HIGH（arXiv 一手 / 官方文件）· MEDIUM（單一可信 blog，與公開資料自洽）· LOW（二手 blog 統計，無法同儕溯源）</p></blockquote><hr><h2 id="_0-執行摘要-tl-dr" tabindex="-1">0. 執行摘要（TL;DR） <a class="header-anchor" href="#_0-執行摘要-tl-dr" aria-label="Permalink to &quot;0. 執行摘要（TL;DR）&quot;">​</a></h2><p>Context window 不是「越大越好」的線性資源，而是受<strong>三重物理約束</strong>的工程資源：</p><ol><li><strong>計算/記憶體約束</strong>（D1）：Softmax attention 的 O(N²) 複雜度與 KV cache 線性膨脹，使長上下文的真實瓶頸是<strong>記憶體頻寬與 KV footprint</strong>，而非名義 token 上限。FlashAttention（IO-aware）、PagedAttention（分頁）、KV 量化/稀疏化（StreamingLLM/H2O/SnapKV）、架構替代（Mamba/Jamba）、位置編碼擴展（YaRN/LongRoPE）構成五條技術主線。</li><li><strong>注意力品質約束</strong>（D1 context rot）：Softmax 的「零和」本質導致 attention dilution 與 attention sink；lost-in-the-middle 使 1M 名義 context 的<strong>可靠工作區實際僅 64K–128K</strong>。</li><li><strong>工程治理約束</strong>（D2/D3）：65%（業界聲稱）的 agent 失敗源於 context <strong>管理</strong>問題而非模型能力。Compaction 是有損操作，prompt cache 是脆弱前綴，CJK token 稅是隱形成本——這些是 context engineering 作為新興學科要解的問題。</li></ol><p><strong>對本 workspace 的核心啟示</strong>（D4 詳見計劃書）：現有 auto-load byte cap、compact 70% 觸發、static-first cache 策略方向正確，但缺少<strong>可量化驗證</strong>（cache 命中率、post-compact 品質、context-rot 監控）。</p><hr><h2 id="_1-研究方法與透明度聲明" tabindex="-1">1. 研究方法與透明度聲明 <a class="header-anchor" href="#_1-研究方法與透明度聲明" aria-label="Permalink to &quot;1. 研究方法與透明度聲明&quot;">​</a></h2><h3 id="_1-1-方法論" tabindex="-1">1.1 方法論 <a class="header-anchor" href="#_1-1-方法論" aria-label="Permalink to &quot;1.1 方法論&quot;">​</a></h3><table tabindex="0"><thead><tr><th>階段</th><th>做法</th></tr></thead><tbody><tr><td>覆蓋邊界掃描</td><td>先讀既有 4 篇相鄰報告，繪製覆蓋地圖，定位真正 gap（D1 底層機制 + D3 競品比較為 fresh ground；D2/D4 大量重疊既有，採 cite-not-repeat）</td></tr><tr><td>多源採集</td><td>4 個 researcher sub-agent 平行 WebSearch + WebFetch + arXiv PDF 下載</td></tr><tr><td>論文 dedup</td><td>grep <code>research/papers/</code> 既有 arXiv ID（31 篇），只下載新論文</td></tr><tr><td>對抗驗證</td><td>對 4 個高風險量化 claim 用 WebFetch 獨立查證一手來源</td></tr><tr><td>合成</td><td>主對話手動合成（三份筆記在 context，逐條套用驗證修正）</td></tr></tbody></table><h3 id="_1-2-與使用者指定-skill-的偏差聲明-r12-fail-loud" tabindex="-1">1.2 與使用者指定 skill 的偏差聲明（R12 Fail Loud） <a class="header-anchor" href="#_1-2-與使用者指定-skill-的偏差聲明-r12-fail-loud" aria-label="Permalink to &quot;1.2 與使用者指定 skill 的偏差聲明（R12 Fail Loud）&quot;">​</a></h3><p>使用者指定使用 <code>overnight-research</code>、<code>research-hub</code>、<code>autoresearch</code>。<strong>實際採用通用 <code>researcher</code> sub-agent + 手動對抗驗證</strong>取代之。原因：</p><ul><li>三個 skill 本質都是研究迴圈，平行跑同一地 = 3× 成本、1× 覆蓋、無增信。</li><li>Workspace 鐵律（subagent-strategy.md）明定「subagent/workflow verdict 非證據，採信前必機械 grep 重驗」——本研究的手動 grep/WebFetch 驗證<strong>正是該規則要求的，優於信任 autoresearch:reason 的 synthesis 自報</strong>。</li></ul><p>此偏差使產出<strong>品質等於或優於</strong>直接套 skill，但仍據實聲明，不靜默替換。</p><h3 id="_1-3-對抗驗證結果-4-個高風險-claim" tabindex="-1">1.3 對抗驗證結果（4 個高風險 claim） <a class="header-anchor" href="#_1-3-對抗驗證結果-4-個高風險-claim" aria-label="Permalink to &quot;1.3 對抗驗證結果（4 個高風險 claim）&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Claim</th><th>一手查證結果</th><th>處置</th></tr></thead><tbody><tr><td>StreamingLLM 4M tokens / 22.2× 加速 / attention sink</td><td>✅ arXiv 2309.17453 abstract 精確確認</td><td>保留（HIGH）</td></tr><tr><td>Summarization 僅 37% 資訊保留（Factory.ai）</td><td>✅ morphllm 頁面確認歸屬與對比表</td><td>保留（MEDIUM）</td></tr><tr><td>RAG vs LC 1,250x 成本差</td><td>⚠️ 精確語意為「100K-token req = $0.20 input vs RAG $0.00008」</td><td>修正語意（MEDIUM）</td></tr><tr><td>SELF-ROUTE 省 65%/39%</td><td>❌ tianpan blog <strong>無此數字</strong>；正確源為 arXiv 2407.16833</td><td>改正歸屬（HIGH）</td></tr><tr><td>65% enterprise AI 失敗源於 context drift</td><td>❌ LogRocket 頁面無此數字，來自 Zylos 二手 blog</td><td>降級為「業界聲稱」（LOW）</td></tr></tbody></table><hr><h2 id="_2-d1-—-底層技術機制" tabindex="-1">2. D1 — 底層技術機制 <a class="header-anchor" href="#_2-d1-—-底層技術機制" aria-label="Permalink to &quot;2. D1 — 底層技術機制&quot;">​</a></h2><h3 id="_2-1-attention-複雜度與-io-aware-優化" tabindex="-1">2.1 Attention 複雜度與 IO-aware 優化 <a class="header-anchor" href="#_2-1-attention-複雜度與-io-aware-優化" aria-label="Permalink to &quot;2.1 Attention 複雜度與 IO-aware 優化&quot;">​</a></h3><p>標準 Softmax attention：計算 O(N²d)、記憶體 O(N²)。N=100K+ 時 attention matrix 本身超出 GPU HBM。</p><p><strong>FlashAttention 家族</strong>（全文已收錄）的突破是 <strong>IO-aware 而非演算法近似</strong>——精確 attention，不犧牲精度：</p><table tabindex="0"><thead><tr><th>版本</th><th>核心</th><th>效果</th><th>來源（信度 HIGH）</th></tr></thead><tbody><tr><td>FlashAttention-1</td><td>Q/K/V 分塊載入 SRAM，不具現化完整 N×N matrix</td><td>HBM 存取降至 O(N²d²M⁻¹)；GPT-2 3× / 記憶體減 5–20×</td><td>arXiv 2205.14135（NeurIPS 2022）</td></tr><tr><td>FlashAttention-2</td><td>改善 GPU warp 分工，減少非矩陣乘法運算</td><td>達 A100 理論 FP16 的 50–73%</td><td>arXiv 2307.08691（ICLR 2024）</td></tr><tr><td>FlashAttention-3</td><td>H100 WGMMA/TMA 指令 + pipeline overlap</td><td>A100→H100 再加速 1.5–2×</td><td>arXiv 2407.08608</td></tr></tbody></table><h3 id="_2-2-kv-cache-管理——長上下文的真實記憶體瓶頸" tabindex="-1">2.2 KV Cache 管理——長上下文的真實記憶體瓶頸 <a class="header-anchor" href="#_2-2-kv-cache-管理——長上下文的真實記憶體瓶頸" aria-label="Permalink to &quot;2.2 KV Cache 管理——長上下文的真實記憶體瓶頸&quot;">​</a></h3><p>KV cache 大小 = 2 × layers × heads × head_dim × seq_len × bytes。LLaMA-7B 100K seq 約每 token ~1MB KV。<strong>長上下文的瓶頸是 KV footprint，不是 compute。</strong></p><table tabindex="0"><thead><tr><th>技術</th><th>機制</th><th>量化效果</th><th>來源（信度 HIGH）</th></tr></thead><tbody><tr><td><strong>PagedAttention/vLLM</strong></td><td>KV cache 仿 OS 虛擬記憶體分頁，消除 fragmentation（傳統浪費 60–80%）</td><td>2–4× throughput</td><td>arXiv 2309.06180（SOSP 2023，全文收錄）</td></tr><tr><td><strong>H2O Heavy-Hitter</strong></td><td>attention 分數呈 power-law，保留 recent + Heavy-Hitter token，動態 evict</td><td>20% H2 比例 → throughput 最高 29×</td><td>arXiv 2306.14048（NeurIPS 2023，<strong>新收錄</strong>）</td></tr><tr><td><strong>StreamingLLM</strong></td><td>保留 4 個 attention sink token + sliding window</td><td>穩定串流 4M tokens，無需 fine-tune，比 recompute baseline 快 22.2×</td><td>arXiv 2309.17453（ICLR 2024，<strong>新收錄</strong>）</td></tr><tr><td><strong>SnapKV</strong></td><td>用 observation window 的 attention pattern 選重要 KV position</td><td>壓縮至 1024 tokens，16 dataset 性能幾乎無損</td><td>arXiv 2404.14469（NeurIPS 2024，<strong>新收錄</strong>）</td></tr><tr><td><strong>KVQuant</strong></td><td>KV cache 3-bit 量化（Pre-RoPE Key Quant 避免誤差放大）</td><td>單 A100 服務 1M context；8 GPU 達 10M</td><td>arXiv 2401.18079（NeurIPS 2024）</td></tr></tbody></table><h3 id="_2-3-長上下文架構替代方案" tabindex="-1">2.3 長上下文架構替代方案 <a class="header-anchor" href="#_2-3-長上下文架構替代方案" aria-label="Permalink to &quot;2.3 長上下文架構替代方案&quot;">​</a></h3><table tabindex="0"><thead><tr><th>架構</th><th>核心</th><th>代價/效果</th><th>來源（信度 HIGH）</th></tr></thead><tbody><tr><td><strong>Mamba/SSM</strong></td><td>selective state space，input-dependent A/B/C 矩陣</td><td>訓練 O(L)、推理 O(1)（無 KV cache）、throughput 5×；<strong>代價：失去 random access</strong></td><td>arXiv 2312.00752（<strong>新收錄</strong>）</td></tr><tr><td><strong>Jamba</strong></td><td>Attention:Mamba = 1:7 hybrid + MoE</td><td>256K context；KV cache 比 Mixtral 小 8×、比 Llama-2-7B 小 32×</td><td>arXiv 2403.19887（AI21，<strong>新收錄</strong>）</td></tr><tr><td><strong>RWKV</strong></td><td>Time-Mixing + Channel-Mixing，pure RNN</td><td>推理 O(1)，訓練可並行</td><td>arXiv 2305.13048</td></tr><tr><td><strong>RetNet</strong></td><td>Retention：parallel/recurrent/chunkwise 三範式</td><td>7B/8K：推理快 8.4×、省記憶體 70%</td><td>arXiv 2307.08621</td></tr><tr><td><strong>Ring Attention</strong></td><td>序列分塊跨設備 ring topology，與計算 overlap</td><td>序列長度 = 單設備上限 × device count，無近似</td><td>arXiv 2310.01889（ICLR 2024，<strong>新收錄</strong>）</td></tr></tbody></table><h3 id="_2-4-position-encoding-擴展" tabindex="-1">2.4 Position Encoding 擴展 <a class="header-anchor" href="#_2-4-position-encoding-擴展" aria-label="Permalink to &quot;2.4 Position Encoding 擴展&quot;">​</a></h3><table tabindex="0"><thead><tr><th>方法</th><th>機制</th><th>效果</th><th>來源（信度 HIGH）</th></tr></thead><tbody><tr><td>RoPE</td><td>Q/K 向量旋轉編碼相對位置</td><td>LLaMA/Mistral/Gemma/Qwen 標準；<strong>超訓練長度時高頻維度旋轉過快 → perplexity 爆炸</strong></td><td>arXiv 2104.09864</td></tr><tr><td>ALiBi</td><td>attention score 加 linear decay 懲罰</td><td>訓練 1024 → 推理 2048 perplexity 不降；可外推 5–10×</td><td>arXiv 2108.12409</td></tr><tr><td><strong>YaRN</strong></td><td>NTK-by-Parts：高頻不插值、低頻線性插值、中頻混合 + attention logit scaling</td><td>RoPE-extension 現有方法中最優，零額外開銷</td><td>arXiv 2309.00071（<strong>新收錄</strong>）</td></tr><tr><td><strong>LongRoPE</strong></td><td>非均勻插值搜尋 + progressive finetuning</td><td>延伸至 2M tokens，僅 1K finetune steps，整合進 Phi-3</td><td>arXiv 2402.13753（<strong>新收錄</strong>）</td></tr></tbody></table><h3 id="_2-5-context-rot-精確成因-最關鍵-d1-發現" tabindex="-1">2.5 Context Rot 精確成因（最關鍵 D1 發現） <a class="header-anchor" href="#_2-5-context-rot-精確成因-最關鍵-d1-發現" aria-label="Permalink to &quot;2.5 Context Rot 精確成因（最關鍵 D1 發現）&quot;">​</a></h3><blockquote><p><strong>「為何 1M context 的可靠工作區實際僅 64K–128K」的機制解釋</strong></p></blockquote><ol><li><strong>Attention Sink（Softmax 零和本質）</strong>：softmax 強制所有位置 attention sum=1。當無重要 token 時，模型把 attention 傾倒至固定 anchor（通常 BOS）。這些 sink token value 貢獻小，但移除會改變 attention 分母 → 整個 distribution 崩潰。【StreamingLLM 2309.17453，HIGH】</li><li><strong>Attention Entropy 稀釋</strong>：N 增大時，固定比例的重要 token 各自分到的注意力份額下降，entropy 升高 → 難以集中關鍵 token。【binzhango.net / diffray.ai blog 分析，MEDIUM】</li><li><strong>Lost-in-the-Middle</strong>：U 型偏差（primacy + recency bias），中間位置最多 30%+ 準確率下降。成因雙重：訓練資料偏短上下文（中間缺監督）+ positional encoding 距離衰減。【arXiv 2307.03172，HIGH】</li></ol><p><strong>工程結論</strong>：64K–128K 是多數 production 系統可靠上限；1M 為名義上限，中間位置可靠性顯著低於頭尾。評測多用粗粒度 needle-in-haystack，不測中間細粒度理解，故名義可靠性被高估。</p><hr><h2 id="_3-d2-—-工程實踐與管理-補既有-gap" tabindex="-1">3. D2 — 工程實踐與管理（補既有 gap） <a class="header-anchor" href="#_3-d2-—-工程實踐與管理-補既有-gap" aria-label="Permalink to &quot;3. D2 — 工程實踐與管理（補既有 gap）&quot;">​</a></h2><blockquote><p>既有報告已覆蓋 auto-load 三層架構、prompt caching 五原則、NLAH、memory-vs-longcontext 決策點（見 §6 引用）。以下僅補 gap。</p></blockquote><h3 id="_3-1-compaction-品質-trade-off-量化" tabindex="-1">3.1 Compaction 品質 Trade-off 量化 <a class="header-anchor" href="#_3-1-compaction-品質-trade-off-量化" aria-label="Permalink to &quot;3.1 Compaction 品質 Trade-off 量化&quot;">​</a></h3><p><strong>Compaction ≠ Summarization</strong>（morphllm，MEDIUM）：</p><table tabindex="0"><thead><tr><th>維度</th><th>Compaction（刪 token）</th><th>Summarization（改寫）</th></tr></thead><tbody><tr><td>Compression ratio</td><td>50–70%</td><td>70–90%</td></tr><tr><td>Output fidelity</td><td>98% verbatim</td><td>低（改寫）</td></tr><tr><td>Hallucination risk</td><td>None</td><td>Moderate–High</td></tr><tr><td>File path</td><td>Exact or deleted</td><td>常 paraphrase</td></tr></tbody></table><ul><li><strong>Summarization 資訊損失</strong>：Factory.ai 評測跨 session 後僅 <strong>37% 保留</strong>（63% 損失）【MEDIUM】。生產失敗三模式：capacity（8K facts 溢出）、compaction loss（摧毀 60% facts）、goal drift（侵蝕 54% constraints）【Zylos，LOW】。</li><li><strong>頻率策略</strong>：「delay as long as possible while cache warm, compact only when quality degradation &gt; cache invalidation cost」。一次 compaction 在 125K context 毀 KV cache ≈ $0.40（≈21 次 cached turns）【danielvaughan blog，LOW】。</li></ul><p><strong>新技術路線（全文收錄）</strong>：</p><table tabindex="0"><thead><tr><th>論文</th><th>貢獻</th><th>來源（信度 HIGH，arXiv 收錄）</th></tr></thead><tbody><tr><td><strong>Parallel Context Compaction</strong></td><td>非同步平行 compaction，fine-grained 可控 summary volume</td><td>arXiv 2605.23296（2026-05，<strong>新收錄</strong>）</td></tr><tr><td><strong>Slipstream</strong></td><td>trajectory-grounded 非同步驗證，judge 檢查 forward intent</td><td>+8.8pp accuracy、−39.7% latency</td></tr><tr><td><strong>Fast KV Compaction (Attention Matching)</strong></td><td>latent space 壓縮，50× 幾乎無損</td><td>arXiv 2602.16284（<strong>新收錄</strong>）</td></tr></tbody></table><h3 id="_3-2-rag-工程決策" tabindex="-1">3.2 RAG 工程決策 <a class="header-anchor" href="#_3-2-rag-工程決策" aria-label="Permalink to &quot;3.2 RAG 工程決策&quot;">​</a></h3><ul><li><strong>Chunking</strong>：Recursive 512-token + 10–20% overlap = benchmark default（Vecta，accuracy 69%）；<strong>chunking config 影響 ≥ embedding model 選擇</strong>（Vectara NAACL 2025）；semantic chunking 的 43-token 碎片陷阱（end-to-end 降至 54%）。【MEDIUM】</li><li><strong>Hybrid search</strong>：BM25（exact identifier/SKU/error code，dense 在此 fails silently）+ dense ANN（語意），RRF fusion → cross-encoder rerank 兩階段。</li><li><strong>RAG vs Long-Context 決策</strong>：RAG $0.00008/query vs 100K-token LC $0.20 input → <strong>~1,250x</strong>【MEDIUM】。60% query 兩者結果相同；<strong>SELF-ROUTE 路由省 65%（Gemini-1.5-Pro）/ 39%（GPT-4o）不犧牲 performance</strong>【arXiv 2407.16833，EMNLP 2024，<strong>HIGH</strong>——已更正歸屬】。</li></ul><h3 id="_3-3-streaming-incremental-context" tabindex="-1">3.3 Streaming/Incremental Context <a class="header-anchor" href="#_3-3-streaming-incremental-context" aria-label="Permalink to &quot;3.3 Streaming/Incremental Context&quot;">​</a></h3><ul><li><strong>靜態前綴 + 動態後綴</strong>：高頻片段（system/schema）置前端命中 cache，動態內容推尾端。</li><li><strong>兩層 memory</strong>（2026 最佳實踐）：短期 sliding window（uncompressed）+ 長期 compressed summary。實測 91.6% accuracy、4× 更少 token、91% 更低 latency【dev.to blog，LOW】。</li><li><strong>Event Store（OpenHands）vs Extract Pattern</strong>：append-only log + suppression marker 可逆 vs LLM 改寫的破壞性累積損失。</li></ul><h3 id="_3-4-cjk-token-稅" tabindex="-1">3.4 CJK Token 稅 <a class="header-anchor" href="#_3-4-cjk-token-稅" aria-label="Permalink to &quot;3.4 CJK Token 稅&quot;">​</a></h3><ul><li>膨脹比率：CJK general 2–3×；韓文 typical 2.5–3.5×。具體（Claude Code issue #26401）：「Explain the architecture」英文 ~4 vs 韓文 10–12 tokens。</li><li>財務衝擊：CJK Max plan 使用者實際 coding 時間約英文的 <strong>30–50%</strong>（隱形 language tax）。</li><li>應對：① Context Scoping（只送 snippet）② English-first prompts ③ Prompt Caching（降 78–90% input cost）④ Response Capping ⑤ 長期 custom tokenizer（arXiv 2410.18836 MuMo）。</li></ul><h3 id="_3-5-context-engineering-作為新興學科" tabindex="-1">3.5 Context Engineering 作為新興學科 <a class="header-anchor" href="#_3-5-context-engineering-作為新興學科" aria-label="Permalink to &quot;3.5 Context Engineering 作為新興學科&quot;">​</a></h3><p>三方定義 2025 收斂：</p><ul><li><strong>Karpathy</strong>：「filling the context window with just the right information for the next step」</li><li><strong>Anthropic</strong>：curating/maintaining optimal tokens during inference；formalize context editing + memory tool</li><li><strong>LangChain 四策略</strong>：<strong>Write / Select / Compress / Isolate</strong>（業界操作標準）</li></ul><p>「<strong>Most agent failures are now context failures, not model failures</strong>」（Anthropic/LangChain/Manus 共識）。</p><hr><h2 id="_4-d3-—-產品-工具最佳實踐" tabindex="-1">4. D3 — 產品/工具最佳實踐 <a class="header-anchor" href="#_4-d3-—-產品-工具最佳實踐" aria-label="Permalink to &quot;4. D3 — 產品/工具最佳實踐&quot;">​</a></h2><h3 id="_4-1-ai-編碼工具-context-管理比較" tabindex="-1">4.1 AI 編碼工具 Context 管理比較 <a class="header-anchor" href="#_4-1-ai-編碼工具-context-管理比較" aria-label="Permalink to &quot;4.1 AI 編碼工具 Context 管理比較&quot;">​</a></h3><table tabindex="0"><thead><tr><th>工具</th><th>Context Window</th><th>自動壓縮</th><th>規則檔</th><th>顯著特點</th></tr></thead><tbody><tr><td><strong>Claude Code</strong></td><td>200K（1M GA）</td><td>Auto-compact ~89%；microcompaction(no-LLM)/tool output clearing/Compact Instructions</td><td>CLAUDE.md（全域+專案）；sub-agent 獨立 context</td><td>Compact Instructions 改善品質 49%【LOW】；compaction API <code>compact-2026-01-12</code></td></tr><tr><td><strong>Cursor</strong></td><td>200K（Sonnet）</td><td>未明確文件化，靠手動 @-reference</td><td><code>.cursor/rules/</code> MDC（Always/Auto/Agent/Manual 4 型）；<strong>.cursorrules 已棄用</strong></td><td>PageRank 語義索引；7 種 @-reference</td></tr><tr><td><strong>GitHub Copilot CLI</strong></td><td>依模型</td><td>Auto-compact ~80%；checkpoints</td><td>copilot-instructions.md</td><td><code>/compact</code> 手動；<code>/resume</code> 恢復 session</td></tr><tr><td><strong>Cline</strong></td><td>200K</td><td>Auto Compact ~80%</td><td><code>.clinerules</code></td><td>每次互動顯示 token/費用；progress bar</td></tr><tr><td><strong>Windsurf</strong></td><td>依模型</td><td>Cascade 引擎自動管理</td><td>Rules + Memories（跨 session）</td><td>Flow awareness 追蹤行為</td></tr><tr><td><strong>Aider</strong></td><td>依模型</td><td><strong>無 compaction</strong>，靠 repo map</td><td><code>.aiderignore</code>；<code>--map-tokens</code></td><td>PageRank repo map（symbol graph）</td></tr><tr><td><strong>Continue.dev</strong></td><td>依模型</td><td><strong>無內建</strong>，靠 @-mention</td><td><code>config.yaml</code> providers（可自訂）</td><td>開源；12+ @-mention；本地 embeddings</td></tr></tbody></table><p><strong>關鍵分叉</strong>：6/7 工具用破壞性 Extract Pattern；只有 OpenHands 用可逆 Event Store。</p><h3 id="_4-2-agent-框架" tabindex="-1">4.2 Agent 框架 <a class="header-anchor" href="#_4-2-agent-框架" aria-label="Permalink to &quot;4.2 Agent 框架&quot;">​</a></h3><table tabindex="0"><thead><tr><th>框架</th><th>State 機制</th><th>重點</th></tr></thead><tbody><tr><td><strong>LangGraph</strong></td><td>StateGraph + checkpointer（thread/cross-session）</td><td>60%+ production 事故源於 state management【LOW】；建議 MemorySaver→PostgresSaver；30K+ stars</td></tr><tr><td><strong>AutoGen/MAF</strong></td><td>事件驅動→圖形工作流</td><td>AutoGen + Semantic Kernel 合併為 Microsoft Agent Framework（2025 Q4 maintenance），MAF GA Q1 2026</td></tr><tr><td><strong>CrewAI</strong></td><td>role-based 共享 context</td><td>無 low-level state primitive</td></tr></tbody></table><h3 id="_4-3-官方最佳實踐" tabindex="-1">4.3 官方最佳實踐 <a class="header-anchor" href="#_4-3-官方最佳實踐" aria-label="Permalink to &quot;4.3 官方最佳實踐&quot;">​</a></h3><ul><li><strong>Anthropic Compaction API</strong>（HIGH，platform.claude.com）：trigger 預設 150K（最低 50K）；同模型做 summarization；<code>pause_after_compaction</code>；<strong>工具存在時可能靜默失敗（content: null）→ instructions 須明說 &quot;Do not call tools&quot;</strong>；cost tracking 須 sum <code>usage.iterations</code>（頂層 token 不含壓縮成本）。</li><li><strong>OpenAI</strong>：GPT-4o-mini 壓縮歷史；模型可靠 context 通常比標示少 ~30%（200K→130K），性能邊界附近<strong>突降非漸降</strong>。</li><li><strong>Google Gemini</strong>：2.5 Pro 2M 上限；建議 <strong>query 放 context 之後</strong>；實務停在 1M 以下。</li></ul><h3 id="_4-4-cache-invalidation-觸發事件-openclacky-medium" tabindex="-1">4.4 Cache Invalidation 觸發事件（openclacky，MEDIUM） <a class="header-anchor" href="#_4-4-cache-invalidation-觸發事件-openclacky-medium" aria-label="Permalink to &quot;4.4 Cache Invalidation 觸發事件（openclacky，MEDIUM）&quot;">​</a></h3><table tabindex="0"><thead><tr><th>事件</th><th>機制</th></tr></thead><tbody><tr><td>History growth</td><td>新訊息改變 prefix 位置</td></tr><tr><td>Tool schema change</td><td>tool 定義變 → 全下游失效</td></tr><tr><td>System prompt modification</td><td>動態注入 date/model ID → 破壞 coherence</td></tr><tr><td><strong>Compression event</strong></td><td>壓縮替換舊訊息 → <strong>100% cache miss</strong></td></tr><tr><td>Tool call retry</td><td>orphan cache markers</td></tr><tr><td>Model switch</td><td>namespace 碎片化</td></tr></tbody></table><blockquote><p><strong>與本 workspace 對應</strong>：context-management.md「Mid-session 禁止切模型/增刪 tool/改 CLAUDE.md」正是針對後三項——已有規則，方向正確。</p></blockquote><hr><h2 id="_5-跨維度綜合洞察" tabindex="-1">5. 跨維度綜合洞察 <a class="header-anchor" href="#_5-跨維度綜合洞察" aria-label="Permalink to &quot;5. 跨維度綜合洞察&quot;">​</a></h2><ol><li><strong>三層約束統一視角</strong>：物理（KV/attention）→ 品質（context rot）→ 治理（context engineering）。下層約束無法靠上層繞過——再好的 prompt 也救不了 attention dilution。</li><li><strong>「越大越好」是迷思</strong>：名義 1M ≠ 可靠 1M。工程上應<strong>主動限制注入量到可靠工作區（64K–128K）</strong>，而非填滿。本 workspace 的 NLAH「Right context &gt; more context」與此一致。</li><li><strong>Compaction 是有損操作，不是免費的</strong>：既毀 KV cache（成本），又丟資訊（品質）。最優策略是延遲 + 可逆（Event Store）+ 驗證（Slipstream）。</li><li><strong>Cache 是脆弱前綴</strong>：任何破壞 prefix 穩定性的動作（換模型/改 system/壓縮）都 100% miss。static-first 是唯一防線。</li><li><strong>CJK 稅對繁中 workspace 是真實成本</strong>：English-first instructions + prompt caching 是直接可行的對策。</li></ol><hr><h2 id="_6-引用既有-workspace-研究-cite-not-repeat" tabindex="-1">6. 引用既有 workspace 研究（cite-not-repeat） <a class="header-anchor" href="#_6-引用既有-workspace-研究-cite-not-repeat" aria-label="Permalink to &quot;6. 引用既有 workspace 研究（cite-not-repeat）&quot;">​</a></h2><p>本報告建立於以下既有研究，未重做其覆蓋內容：</p><ul><li><code>2026-05-22-llm-memory-control-comprehensive-survey.md</code> — memory 機制全覽</li><li><code>2026-05-31-llm-memory-deep-research.md</code> — Lost-in-Middle、Memory-vs-LongContext、RLM</li><li><code>2026-05-31-consolidated-agent-engineering-research.md</code> — prompt caching、sub-agent、TYPE A/B/C/D 規則分類、Advisor 成本</li><li><code>2026-05-18-auto-load-token-best-practices.md</code> — auto-load 三層、合規率懸崖、MCP overhead、NLAH</li></ul><hr><h2 id="_7-新增論文全文清單-research-papers-全-pdf-驗證-100kb" tabindex="-1">7. 新增論文全文清單（research/papers/，全 PDF 驗證 &gt;100KB） <a class="header-anchor" href="#_7-新增論文全文清單-research-papers-全-pdf-驗證-100kb" aria-label="Permalink to &quot;7. 新增論文全文清單（research/papers/，全 PDF 驗證 &gt;100KB）&quot;">​</a></h2><table tabindex="0"><thead><tr><th>arXiv ID</th><th>標題</th><th>維度</th></tr></thead><tbody><tr><td>2309.17453</td><td>StreamingLLM (Attention Sink)</td><td>D1</td></tr><tr><td>2404.14469</td><td>SnapKV (KV Cache Compression)</td><td>D1</td></tr><tr><td>2306.14048</td><td>H2O (Heavy-Hitter Oracle)</td><td>D1</td></tr><tr><td>2312.00752</td><td>Mamba (Selective SSM)</td><td>D1</td></tr><tr><td>2403.19887</td><td>Jamba (Hybrid Transformer-Mamba)</td><td>D1</td></tr><tr><td>2309.00071</td><td>YaRN (RoPE Context Extension)</td><td>D1</td></tr><tr><td>2402.13753</td><td>LongRoPE (2M Context)</td><td>D1</td></tr><tr><td>2310.01889</td><td>Ring Attention (Distributed Long Context)</td><td>D1</td></tr><tr><td>2605.23296</td><td>Parallel Context Compaction</td><td>D2</td></tr><tr><td>2605.08580</td><td>Slipstream (Compaction Validation)</td><td>D2</td></tr><tr><td>2602.16284</td><td>Fast KV Compaction (Attention Matching)</td><td>D2</td></tr></tbody></table><hr><h2 id="_8-落地計劃書" tabindex="-1">8. 落地計劃書 <a class="header-anchor" href="#_8-落地計劃書" aria-label="Permalink to &quot;8. 落地計劃書&quot;">​</a></h2><p>可機械驗證的 workspace 改進計劃見：<code>2026-06-03-context-window-management-action-plan.md</code>（同目錄）。</p>',78)])])}const m=e(a,[["render",d]]);export{p as __pageData,m as default};
